-- Lugares das festas encontradas na RA (25/11/2026)
on conflict (id) do update set name = excluded.name, kind = excluded.kind, category_id = excluded.category_id, neighborhood = excluded.neighborhood,
  address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, geo_precision = excluded.geo_precision,
  source_url = excluded.source_url, checked_at = excluded.checked_at, is_active = true;
